const HOST_EVIDENCE = 'the guard warning (tag and opt-in name) and no connection attempt';
const cases = [
  ['opt-in absent', base, null, guard, 'the guard warning (tag and opt-in name)'],
  ['opt-in empty', base, '', guard, 'the guard warning (tag and opt-in name)'],
  ['opt-in names another database', base, db + '_other', guard, 'the guard warning (tag and opt-in name)'],
  ['non-local host', at('db.invalid', null), db, guard, 'the guard warning (tag and opt-in name)'],
  ['production-named database', at(null, 'verdura_production'), 'verdura_production', refused('Integration tests refuse to run against a database named'), 'the integration-setup refusal'],
  ['unparsable DATABASE_URL', 'not a url', 'not a url', refused('Integration tests have no readable DATABASE_URL'), 'the integration-setup refusal'],
  // A host query parameter overrides the URL authority in the database engine (Prisma 5.22 uses the
  // last decoded `host` value): any such parameter refuses execution, whatever its value or casing.
  ['?host=db.invalid', q('host=db.invalid'), db, hostRefusal, HOST_EVIDENCE],
  ['?host=127.0.0.1', q('host=127.0.0.1'), db, hostRefusal, HOST_EVIDENCE],
  ['?host=localhost', q('host=localhost'), db, hostRefusal, HOST_EVIDENCE],
  ['?host= (empty)', q('host='), db, hostRefusal, HOST_EVIDENCE],
  ['?host=127.0.0.1&host=db.invalid (repeated)', q('host=127.0.0.1&host=db.invalid'), db, hostRefusal, HOST_EVIDENCE],
  ['?%68ost=db.invalid (percent-encoded name)', q('%68ost=db.invalid'), db, hostRefusal, HOST_EVIDENCE],
  ['?HOST=db.invalid', q('HOST=db.invalid'), db, hostRefusal, HOST_EVIDENCE],
  ['?Host=db.invalid', q('Host=db.invalid'), db, hostRefusal, HOST_EVIDENCE],
];
let bad = 0;
cases.forEach(([label, url, optIn, evidence, what], i) => {
  const out = path.join(process.env.HOME, 'nrr-failsafe-' + i + '.json'); fs.rmSync(out, { force: true });
  const env = { ...process.env, DATABASE_URL: url }; delete env.INTEGRATION_DATABASE_URL; delete env[V]; if (optIn !== null) env[V] = optIn;
  const r = spawnSync(process.execPath, ['../../node_modules/jest/bin/jest.js', '--config', './test/jest-integration.json', '--runInBand', '--ci', '--json', '--outputFile=' + out, 'native-round-recovery'], { env, encoding: 'utf8', timeout: 300000 });
  const files = fs.existsSync(out) ? JSON.parse(fs.readFileSync(out, 'utf8')).testResults.filter((f) => f.name.endsWith('native-round-recovery.integration-spec.ts')) : [];
